pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _checkSetMinSum(uint256 val) internal {
        try c.SetMinSum(val) {} catch { return; }
        assertTrue(c.MinSum() == val);
    }

    function testFuzz_checkSetMinSum(uint256 val) public {
        _checkSetMinSum(val);
    }

    receive() external payable {}
}
